user_prompt:
method derivative(xs: array<int>) returns (result: array<int>)
    requires xs.Length > 0
    ensures result.Length == xs.Length - 1
    ensures forall i :: 0 <= i < result.Length ==> result[i] == (i + 1) * xs[i + 1]
{
    var n := xs.Length;
    var res := new int[n - 1];
    var i := 0;
    while i < n - 1
        invariant 0 <= i <= n - 1
        invariant res.Length == n - 1
    {
        res[i] := (i + 1) * xs[i + 1];
        i := i + 1;
    }
    result := res;
}
